     1	// Merges the generated overrides (orca-mac-keybindings.js) into
     2	// ~/.orca/keybindings.json's platforms.linux. See orca.nix.
     3	//
     4	//   node orca-mac-keybindings-merge.js <app>/out/shared <owned.json>
     5	//
     6	// The file is Orca's read-write state, so this owns only what it wrote: a
     7	// sidecar, keybindings.nix-owned.json, records the values of the last write.
     8	//   - a key written last time and no longer generated is removed;
     9	//   - a key whose value the UI has changed since is left as the UI's;
    10	//   - everything else in the file is untouched.
    11	// Then the merged file gets Orca's own conflict check. Orca drops every
    12	// action in a conflicting set at load, so a generated key that clashes with
    13	// a UI shortcut is withdrawn instead, and named, leaving the UI's choice and
    14	// the generated action's Linux default.
    15	const fs = require('fs');
    16	const os = require('os');
    17	const path = require('path');
    18	
    19	// Activation runs under set -e, so a throw here would abandon the rest of
    20	// the switch over a keybinding file. Any failure is one line and exit 0;
    21	// the file is then exactly as it was, since writes only ever rename over it.
    22	process.on('uncaughtException', (e) => {
    23	  console.error(`orca: keybinding merge skipped: ${e.message}`);
    24	  process.exit(0);
    25	});
    26	
    27	const [shared, ownedFile] = process.argv.slice(2);
    28	const kb = require(path.resolve(shared, 'keybindings.js'));
    29	const owned = JSON.parse(fs.readFileSync(ownedFile, 'utf8'));
    30	
    31	const dir = path.join(os.homedir(), '.orca');
    32	const dest = path.join(dir, 'keybindings.json');
    33	const sidecar = path.join(dir, 'keybindings.nix-owned.json');
    34	const isObject = (v) => v !== null && typeof v === 'object' && !Array.isArray(v);
    35	const same = (a, b) => JSON.stringify(a) === JSON.stringify(b);
    36	
    37	// Orca's own writer (G$): whole file to a temp name, rename over, and the
    38	// temp removed if either step fails.
    39	function writeJson(file, value) {
    40	  const tmp = `${file}.nix-${process.pid}-${Date.now()}`;
    41	  try {
    42	    fs.writeFileSync(tmp, `${JSON.stringify(value, null, 2)}\n`, { flag: 'wx' });
    43	    fs.renameSync(tmp, file);
    44	  } catch (e) {
    45	    fs.rmSync(tmp, { force: true });
    46	    throw e;
    47	  }
    48	}
    49	
    50	fs.mkdirSync(dir, { recursive: true });
    51	let doc;
    52	if (!fs.existsSync(dest)) {
    53	  doc = { version: 1, keybindings: {}, platforms: { darwin: {}, linux: {}, win32: {} } };
    54	} else {
    55	  let why = null;
    56	  try {
    57	    doc = JSON.parse(fs.readFileSync(dest, 'utf8'));
    58	    if (!isObject(doc)) why = 'not a JSON object';
    59	  } catch (e) {
    60	    why = e.message;
    61	  }
    62	  if (why !== null) {
    63	    // Orca's loader rejects it too and says so; overwriting would lose
    64	    // whatever the user was halfway through editing.
    65	    console.error(`orca: ${dest}: ${why}; leaving it for Orca to report`);
    66	    process.exit(0);
    67	  }
    68	}
    69	
    70	let prev = {};
    71	try {
    72	  const s = JSON.parse(fs.readFileSync(sidecar, 'utf8'));
    73	  if (!isObject(s?.linux)) throw new Error('no .linux object');
    74	  prev = s.linux;
    75	} catch (e) {
    76	  // No sidecar is a first run. A bad one stops the merge: it decides what
    77	  // may be overwritten, and reading it as empty overwrites every key the UI
    78	  // has changed.
    79	  if (e.code !== 'ENOENT') {
    80	    console.error(`orca: ${sidecar}: ${e.message}; not merging -- delete it to start over`);
    81	    process.exit(0);
    82	  }
    83	}
    84	
    85	const platforms = isObject(doc.platforms) ? doc.platforms : {};
    86	const linux = isObject(platforms.linux) ? { ...platforms.linux } : {};
    87	// Changed since the last write: the UI's now. Absent (reset in the UI)
    88	// is not a change -- the reset target is this table, so it comes back.
    89	const theirs = new Set(Object.keys(prev).filter((id) => id in linux && !same(linux[id], prev[id])));
    90	for (const id of Object.keys(prev)) {
    91	  if (!theirs.has(id)) delete linux[id];
    92	}
    93	// What the UI had on each key about to be overwritten, for a withdrawal
    94	// below to put back. Stale keys are gone by now, so anything left is the UI's.
    95	const before = {};
    96	const written = {};
    97	for (const [id, bindings] of Object.entries(owned)) {
    98	  if (theirs.has(id)) continue;
    99	  if (id in linux) before[id] = linux[id];
   100	  linux[id] = bindings;
   101	  written[id] = bindings;
   102	}
   103	
   104	// What Orca's loader feeds its conflict pass: common, then the platform
   105	// section over it, with its string shorthand and null/false expanded.
   106	// Common is the root's action keys in the legacy shape with no .keybindings.
   107	const common = doc.keybindings === undefined ? doc : isObject(doc.keybindings) ? doc.keybindings : {};
   108	const expand = (v) =>
   109	  v === null || v === false ? [] : typeof v === 'string' ? [v]
   110	    : Array.isArray(v) && v.every((b) => typeof b === 'string') ? v : undefined;
   111	const effective = {};
   112	for (const [id, v] of Object.entries({ ...common, ...linux })) {
   113	  if (kb.isKeybindingActionId(id) && expand(v) !== undefined) effective[id] = expand(v);
   114	}
   115	for (;;) {
   116	  const withdrawn = kb
   117	    .findKeybindingConflicts('linux', effective)
   118	    .flatMap((c) => c.actionIds)
   119	    .filter((id) => id in written);
   120	  // Only generated keys are ever withdrawn. A conflict with none left in it
   121	  // -- between UI shortcuts, or a UI shortcut and the Linux default a
   122	  // withdrawal brought back -- is Orca's to report.
   123	  if (withdrawn.length === 0) break;
   124	  for (const id of new Set(withdrawn)) {
   125	    console.error(`orca: ${id} ${JSON.stringify(written[id])} clashes with a shortcut set in Orca; keeping that one`);
   126	    delete written[id];
   127	    if (id in before) {
   128	      linux[id] = before[id];
   129	    } else {
   130	      delete linux[id];
   131	    }
   132	    const fallback = id in linux ? linux[id] : common[id];
   133	    if (kb.isKeybindingActionId(id) && expand(fallback) !== undefined) effective[id] = expand(fallback);
   134	    else delete effective[id];
   135	  }
   136	}
   137	
   138	doc.version = 1;
   139	doc.platforms = {
   140	  ...platforms,
   141	  darwin: isObject(platforms.darwin) ? platforms.darwin : {},
   142	  linux,
   143	  win32: isObject(platforms.win32) ? platforms.win32 : {},
   144	};
   145	writeJson(dest, doc);
   146	// Every key this table claims, written or withdrawn, at its generated value;
   147	// the UI's keep the value last written. Either way a later UI value reads as
   148	// changed, the UI's, rather than as never owned and free to overwrite.
   149	writeJson(sidecar, {
   150	  linux: { ...Object.fromEntries([...theirs].map((id) => [id, prev[id]])), ...owned, ...written },
   151	});
   152	// Emits Orca's platforms.linux keybinding overrides: every action's macOS
   153	// default, with Mod (Cmd there, Ctrl here) spelled Cmd, which Orca binds to
   154	// Super on Linux. See orca.nix.
   155	//
   156	//   node orca-mac-keybindings.js <app>/out/shared <hyprland-chords.json>
   157	//
   158	// Uses Orca's own keybinding module (out/shared/keybindings.js, the stable
   159	// facade its comment promises) for the definitions, normalisation and the
   160	// conflict check, so a version bump regenerates the table instead of
   161	// silently drifting from it.
   162	const fs = require('fs');
   163	const path = require('path');
   164	
   165	const [shared, chordsFile] = process.argv.slice(2);
   166	const kb = require(path.resolve(shared, 'keybindings.js'));
   167	
   168	// Chords Hyprland binds never reach the window. "SUPER + SHIFT + W" ->
   169	// "Cmd+Shift+W". Mouse, switch and media-key binds cannot be an Orca chord;
   170	// anything else that does not translate is an error, not a free chord.
   171	const MODS = { SUPER: 'Cmd', CTRL: 'Ctrl', CONTROL: 'Ctrl', ALT: 'Alt', SHIFT: 'Shift' };
   172	const KEYS = { return: 'Enter', left: 'ArrowLeft', right: 'ArrowRight', up: 'ArrowUp', down: 'ArrowDown' };
   173	const taken = new Set();
   174	for (const chord of JSON.parse(fs.readFileSync(chordsFile, 'utf8'))) {
   175	  const parts = chord.split('+').map((s) => s.trim());
   176	  const key = parts.pop();
   177	  if (/^(mouse[:_]|XF86)/.test(key) || chord.startsWith('switch:')) continue;
   178	  const mods = parts.map((p) => MODS[p.toUpperCase()]);
   179	  const n = mods.every(Boolean) && kb.normalizeKeybinding([...mods, KEYS[key] ?? key].join('+'));
   180	  if (!n || !n.ok) throw new Error(`cannot translate Hyprland bind "${chord}" to an Orca chord`);
   181	  taken.add(n.value);
   182	}
   183	// A digit-index action's one binding stands for its whole 1-9 family.
   184	const isTaken = (id, binding) =>
   185	  kb.isDigitIndexActionId(id)
   186	    ? [1, 2, 3, 4, 5, 6, 7, 8, 9].some((d) => taken.has(binding.replace(/1$/, String(d))))
   187	    : taken.has(binding);
   188	
   189	const overrides = {};
   190	for (const def of kb.KEYBINDING_DEFINITIONS) {
   191	  const mac = kb.getDefaultBindings(def, 'darwin').map((binding) => {
   192	    const cmd = binding.split('+').map((t) => (t === 'Mod' ? 'Cmd' : t)).join('+');
   193	    const n = kb.normalizeKeybindingWithOptions(cmd, kb.normalizeOptionsForAction(def.id));
   194	    if (!n.ok) throw new Error(`${def.id}: ${cmd}: ${n.error}`);
   195	    return n.value;
   196	  });
   197	  const free = mac.filter((b) => !isTaken(def.id, b));
   198	  if (free.length < mac.length) {
   199	    console.error(`${def.id}: ${mac.filter((b) => isTaken(def.id, b)).join(', ')} is Hyprland's`);
   200	  }
   201	  // Every chord taken: leave the action on its Linux default rather than
   202	  // unbinding it. No macOS binding at all is different -- unbound there, so
   203	  // unbound here ([]). Same as the Linux default: nothing to say.
   204	  if (mac.length > 0 && free.length === 0) continue;
   205	  if (JSON.stringify(free) === JSON.stringify(kb.getDefaultBindings(def, 'linux'))) continue;
   206	  overrides[def.id] = free;
   207	}
   208	
   209	// Orca drops every action in a conflicting set at load, with only a line in
   210	// its diagnostics; fail the build instead.
   211	const conflicts = kb.findKeybindingConflicts('linux', overrides);
   212	if (conflicts.length > 0) {
   213	  throw new Error(`conflicting shortcuts: ${JSON.stringify(conflicts)}`);
   214	}
   215	process.stdout.write(`${JSON.stringify(overrides, null, 2)}\n`);
